{"HelperA.dfy": "if |s| == 0 {
  A.Empty(s, p);
  A.Empty(s, q);
} else {
  O1.Unfold(s, p);
  O2.Select(s[0], p, K.Filter(s[1..], p));
  if s[0] <= p {
    var tail := K.Filter(s[1..], p);
    O1.Unfold([s[0]] + tail, q);
    O2.Select(s[0], q, K.Filter(tail, q));
    if s[0] <= q {
      Prove(s[1..], p, q);
      O1.Unfold(s, q);
      O2.Select(s[0], q, K.Filter(s[1..], q));
    } else {
      Prove(s[1..], p, q);
      O1.Unfold(s, q);
      O2.Select(s[0], q, K.Filter(s[1..], q));
    }
  } else {
    Prove(s[1..], p, q);
    O1.Unfold(s, q);
    O2.Select(s[0], q, K.Filter(s[1..], q));
  }
